{
 "app_name": "phone",
 "api_name": "search_voice_messages",
 "path": "/messages/voice",
 "method": "GET",
 "description": "Show or search text voice_messages between the user and a contact.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from phone app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "query",
   "type": "string",
   "required": false,
   "description": "The search query string.",
   "default": "",
   "constraints": []
  },
  {
   "name": "phone_number",
   "type": "string",
   "required": false,
   "description": "The phone number of the contact to show voice_messages with.",
   "default": null,
   "constraints": []
  },
  {
   "name": "only_latest_per_contact",
   "type": "boolean",
   "required": false,
   "description": "If set to true, only the latest message from each contact will be shown.",
   "default": false,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 20.0"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the voice messages by prefixed with +/- to reflect ascending/descending. Valid attributes: created_at. If both query and sort_by are given and non-empty, results will be first ranked by query relevance, then paginated, and will then be sorted by the given attribute within each page. If both query and sort_by are not given, null, or empty, sort_by will default to -created_at.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "voice_message_id": 1,
    "sender": {
     "contact_id": 1,
     "name": "string",
     "phone_number": "string"
    },
    "receiver": {
     "contact_id": 1,
     "name": "string",
     "phone_number": "string"
    },
    "message": "string",
    "sent_at": "2019-01-01T00:00:00"
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}
